const steps = [];
for (const row of rowsOf('Lane 5 · Read SEQUENCES')) {
  if (String(row.sequence_id).trim() !== SEQUENCE_ID || !isTrue(row.active)) continue;
  const step = Number(row.step);
  const delay = Number(String(row.delay_days).trim() === '' ? NaN : row.delay_days);
  const basis = String(row.delay_basis ?? '').trim();
  if (!Number.isInteger(step) || step < 1 || !Number.isFinite(delay) || basis !== 'launch') {
    problem(`step ${row.step_key || '?'} has an invalid step, delay_days or delay_basis (must be a number and "launch")`, { entity_id: row.step_key || SEQUENCE_ID });
    continue;
  }
  steps.push({ ...row, step, due_at: addDays(T0, delay) });
}
const due = steps.filter((row) => row.due_at.toMillis() <= now.toMillis());
if (!due.length) return out;

// ---- placeholders (BRIEF text may contain {{launch_date}} style tokens, so fill those first)
const realLaunch = parseDate(S.LAUNCH_DATE);
const dateText = (d) => (d ? d.setLocale('en').toFormat('cccc, d LLLL') : '');
const base = {
  launch_date: dateText(realLaunch),
  public_launch_date: dateText(realLaunch?.plus({ days: Number(S.EARLY_ACCESS_DAYS) })),
  waitlist_form_url: S.WAITLIST_FORM_URL, sender_name: S.SENDER_NAME, unsubscribe_line: S.UNSUBSCRIBE_LINE,
};
const brief = {};
for (const row of rowsOf('Lane 5 · Read BRIEF')) { const key = String(row.key ?? '').trim(); if (key) brief[key] = String(row.value ?? '').trim(); }
const briefValues = {};
for (const key of ['brand_name', 'brand_instagram', 'collection_name', 'founder_name', 'offer_percent', 'offer_code']) {
  if (brief[key] !== undefined) briefValues[key] = render(brief[key], base).text;
}
// The discount code may only appear in the launch EMAIL, never in the public channel post.
const { offer_code: offerCode, ...briefPublic } = briefValues;

// ---- channel post: only the latest undone due step is posted, older undone ones are marked done without posting
const undoneChannel = due
  .filter((row) => String(row.channel).trim() === 'telegram_channel' && String(row.broadcast_done_at ?? '').trim() === '')
  .sort((a, b) => a.due_at.toMillis() - b.due_at.toMillis() || a.step - b.step);
if (undoneChannel.length) {
  const latest = undoneChannel[undoneChannel.length - 1];
  const stale = undoneChannel.slice(0, -1).map((row) => row.step_key);
  const post = render(latest.body_template, Object.fromEntries(Object.entries({ ...base, ...briefPublic }).map(([k, v]) => [k, escapeHtml(v)])));
  if (post.missing.length) problem(`channel post ${latest.step_key} has empty or unknown placeholder(s): ${post.missing.join(', ')}`, { entity_id: latest.step_key });
  else out.push({ json: { kind: 'post', is_post: true, needs_email: false, chat_id: String(S.TELEGRAM_CHANNEL_ID), text: post.text.slice(0, 4000), step_key: latest.step_key, stale_keys: stale } });
}

// ---- emails: k = highest due email step; every active lead with launch_step < k gets exactly that step
const emailSteps = due.filter((row) => String(row.channel).trim() === 'email').sort((a, b) => a.step - b.step);
if (emailSteps.length) {
  const stepRow = emailSteps[emailSteps.length - 1];
  const k = stepRow.step;
  const ACTIVE = ['new', 'nurturing', 'nurture_done', 'replied', 'hot'];
  // Cross-lane guard (session 5): Lane 4 reads LEADS at :15 and this lane at :30, and both runs can last ~45 s, so the
  // gap rule alone cannot see an email the other lane is sending right now. A lead Lane 4 will email within the next
  // minute (status new/nurturing, next_action_at blank or due by then) is left to Lane 4; once that email is in its
  // row, the gap rule spaces the launch email. Lane 4 re-reads the row before sending, which covers the other direction.
  const NURTURE_HORIZON_MS = 60 * 1000;
  const reservedForNurture = (lead) => ['new', 'nurturing'].includes(String(lead.status ?? '').trim())
    && (!parseTs(lead.next_action_at) || parseTs(lead.next_action_at).toMillis() <= now.toMillis() + NURTURE_HORIZON_MS);
  const maxSends = Math.max(0, Number(S.MAX_SENDS_PER_RUN) || 0);
  let sends = 0;
  for (const lead of rowsOf('Lane 5 · Read LEADS')) {
    if (sends >= maxSends) break;
    if (!ACTIVE.includes(String(lead.status ?? '').trim())) continue;
    if (!isTrue(lead.consent)) continue;
    if (String(lead.email_allowed ?? '').trim().toUpperCase() === 'FALSE') continue;
    const leadId = String(lead.lead_id ?? '').trim();
    const email = String(lead.email ?? '').trim().toLowerCase();
    const stepRaw = String(lead.launch_step ?? '').trim();
    const launchStep = stepRaw === '' ? 0 : Number(stepRaw);
    const bad = [];
    if (!leadId) bad.push('lead_id');
    if (!email) bad.push('email');
    if (!Number.isInteger(launchStep) || launchStep < 0) bad.push('launch_step');
    if (String(lead.last_contacted_at ?? '').trim() && !parseTs(lead.last_contacted_at)) bad.push('last_contacted_at');
    if (launchStep < k || bad.length) {
      if (bad.length) { problem(`missing or invalid ${bad.join(', ')}`, { entity_type: 'lead', entity_id: leadId || `row ${lead.row_number ?? '?'}` }); continue; }
    } else continue;                                               // already has this (or a later) launch email
    if (!gapOk(lead, now)) continue;                               // too soon after any other automated email
    if (reservedForNurture(lead)) continue;                        // Lane 4 is about to email this lead
    const common = { ...base, ...briefPublic, ...(offerCode !== undefined ? { offer_code: offerCode } : {}) };
    const text = render(stepRow.subject_template, { ...common, first_name: lead.first_name, city: lead.city });
    const html = render(stepRow.body_template, { ...common, first_name: escapeHtml(lead.first_name), city: escapeHtml(lead.city) });
    const missingTokens = [...new Set([...text.missing, ...html.missing])];
    if (missingTokens.length) { problem(`template ${stepRow.step_key} has empty or unknown placeholder(s): ${missingTokens.join(', ')}`, { entity_type: 'lead', entity_id: leadId }); continue; }
    out.push({
      json: {
        kind: 'email', is_post: false, needs_email: true, lead_id: leadId, to_email: email,
        subject: text.text.replace(/\s+/g, ' ').trim(), html: html.text, sender_name: S.SENDER_NAME,
        sequence_id: SEQUENCE_ID, step: k, step_key: stepRow.step_key,
        status_from: String(lead.status).trim(), thread_ids_before: String(lead.thread_ids ?? ''),
      },
    });
    sends++;
  }
}
return out;

// Lane 5 · Demo safety gate: input items carry the recipient in `to_email`.
const S = $('Lane 5 · Settings to object').first().json;
const PUBLIC = ['gmail.com', 'googlemail.com', 'yahoo.com', 'yahoo.in', 'outlook.com', 'hotmail.com', 'live.com', 'icloud.com', 'rediffmail.com', 'proton.me', 'protonmail.com'];
const list = (value) => String(value ?? '').toLowerCase().split(',').map((part) => part.trim()).filter(Boolean);
function checkRecipient(email) {
  const match = /^([a-z0-9._%-]+)(\+[a-z0-9._%-]*)?@([a-z0-9.-]+\.[a-z]{2,})$/.exec(email);
  if (!match) return { ok: false, reason: 'not a single valid email address' };
  const base = `${match[1]}@${match[3]}`;                      // plus-tag removed
  const inboxes = [...list(S.ALLOWED_DEMO_INBOXES), ...list(S.SENDER_EMAIL)];
  const domains = list(S.ALLOWED_EMAIL_DOMAINS).map((d) => d.replace(/^@/, '')).filter((d) => !PUBLIC.includes(d));
  if (inboxes.includes(base)) return { ok: true, reason: 'demo inbox' };
  if (domains.includes(match[3])) return { ok: true, reason: 'demo domain' };
  return { ok: false, reason: 'not in ALLOWED_DEMO_INBOXES or ALLOWED_EMAIL_DOMAINS' };
}
return $input.all().map((item) => {
  const to = String(item.json.to_email ?? '').trim().toLowerCase();
  const check = checkRecipient(to);
  return { json: { ...item.json, safe_to: check.ok ? to : '', gate_ok: check.ok, gate_reason: check.reason } };
});

// Runs once per work item, after its post/email step has finished one way or another.
// Decides what to write back (SEQUENCES for a post, LEADS for an email) and which events to log.
const S = $('Lane 5 · Settings to object').first().json;
// ---- time helpers (SPEC 5.2 / 5.3)
const TZ = 'Asia/Kolkata';
const STAMP = "yyyy-MM-dd'T'HH:mm:ssZZ";
const nowTs = () => $now.setZone(TZ).toFormat(STAMP);
function parseTs(value) {
  if (value === undefined || value === null || String(value).trim() === '') return null;
  const text = String(value).trim();
  const tries = [
    () => DateTime.fromISO(text, { zone: TZ }),
    () => DateTime.fromFormat(text, 'yyyy-MM-dd HH:mm:ss', { zone: TZ }),
    () => DateTime.fromFormat(text, 'yyyy-MM-dd HH:mm', { zone: TZ }),
    () => DateTime.fromFormat(text, 'dd/MM/yyyy HH:mm:ss', { zone: TZ }),
    () => DateTime.fromFormat(text, 'dd/MM/yyyy', { zone: TZ }),
  ];
  for (const attempt of tries) { const d = attempt(); if (d.isValid) return d.setZone(TZ); }
  return null;
}
const parseDate = (value) => parseTs(value)?.startOf('day') ?? null;
const addDays = (dateTime, days) => dateTime.plus({ milliseconds: Number(days) * S.DAY_MS });
function launchAt(S) {
  if (S.IS_DEMO) return parseTs(S.DEMO_LAUNCH_AT);
  const [hour, minute] = String(S.LAUNCH_TIME).split(':').map(Number);
  return parseDate(S.LAUNCH_DATE)?.set({ hour, minute }) ?? null;
}
const gapOk = (row, now) => !parseTs(row.last_contacted_at) || now.toMillis() - parseTs(row.last_contacted_at).toMillis() >= Number(S.MIN_EMAIL_GAP_DAYS) * S.DAY_MS;
const isTrue = (value) => String(value ?? '').trim().toUpperCase() === 'TRUE';
// Rows read from a sheet; an empty tab comes back as one empty item (and blank rows only have a row_number), so drop those.
const rowsOf = (nodeName) => $(nodeName).all().map((item) => item.json).filter((row) => row && Object.entries(row).some(([key, v]) => key !== 'row_number' && String(v ?? '').trim() !== ''));
const now = $now.setZone(TZ);
const input = $json;
// Every work item passes through "Is channel post?", so this is the item of this round whatever path it took.
const ctx = $('Lane 5 · Is channel post?').item.json;
const stamp = (d) => d.toFormat(STAMP);
const events = [];
let target = 'none';
let updates = [];
let outcome = ctx.kind;

if (ctx.kind === 'post') {
  const messageId = input.ok === true ? input.result?.message_id : undefined;
  if (messageId !== undefined && messageId !== null) {
    target = 'sequence'; outcome = 'posted';
    updates = [ctx.step_key, ...(ctx.stale_keys || [])].map((key) => ({ step_key: key, broadcast_done_at: stamp(now) }));
    events.push({ event_type: 'launch_post_published', entity_type: 'sequence', entity_id: ctx.step_key, channel: 'telegram_channel',
      detail: `${ctx.step_key} posted to the channel${ctx.stale_keys?.length ? `; ${ctx.stale_keys.length} older step(s) skipped as stale` : ''}`,
      meta: { step_key: ctx.step_key, message_id: messageId, stale_skipped: ctx.stale_keys || [] } });
  } else {
    // Leave broadcast_done_at blank so the next run tries again.
    outcome = 'post_failed';
    const message = typeof input.error === 'string' ? input.error : (input.error?.message || input.description || 'Telegram returned no message id');
    events.push({ event_type: 'error', entity_type: 'sequence', entity_id: ctx.step_key, channel: 'telegram_channel',
      detail: `channel post ${ctx.step_key} failed: ${message}`, meta: { node: 'Lane 5 · Post to channel', message: String(message).slice(0, 300) } });
  }
} else if (ctx.kind === 'email') {
  const id = ctx.lead_id;
  if (input.gate_ok === false) {
    outcome = 'blocked'; target = 'lead';
    updates = [{ lead_id: id, status: 'blocked', email_allowed: 'FALSE', updated_at: stamp(now) }];
    events.push({ event_type: 'email_blocked', entity_type: 'lead', entity_id: id, status_from: ctx.status_from, status_to: 'blocked', channel: 'email',
      detail: `${ctx.to_email} blocked by the safety gate: ${input.gate_reason}`, meta: { reason: input.gate_reason } });
  } else if (input.id && !input.error) {
    outcome = 'sent'; target = 'lead';
    const threads = String(ctx.thread_ids_before || '').split(',').map((t) => t.trim()).filter(Boolean);
    if (input.threadId) threads.push(String(input.threadId));
    updates = [{ lead_id: id, launch_step: ctx.step, last_contacted_at: stamp(now), thread_ids: threads.slice(-10).join(','), updated_at: stamp(now) }];
    events.push({ event_type: 'email_sent', entity_type: 'lead', entity_id: id, channel: 'email', detail: `${ctx.sequence_id} step ${ctx.step} sent`,
      meta: { sequence_id: ctx.sequence_id, step: ctx.step, thread_id: String(input.threadId ?? '') } });
  } else {
    // The lead keeps launch_step, so the next run simply tries again.
    outcome = 'email_failed';
    const message = typeof input.error === 'string' ? input.error : (input.error?.message || JSON.stringify(input.error ?? 'Gmail returned no message id'));
    events.push({ event_type: 'email_failed', entity_type: 'lead', entity_id: id, channel: 'email',
      detail: `${ctx.sequence_id} step ${ctx.step} not sent: ${message}`, meta: { sequence_id: ctx.sequence_id, step: ctx.step, error: String(message).slice(0, 300) } });
  }
} else {
  events.push({ event_type: 'error', entity_type: ctx.entity_type || 'sequence', entity_id: ctx.entity_id || '', channel: 'sheet',
    detail: ctx.pick_error, meta: { node: 'Lane 5 · Pick launch work', message: ctx.pick_error } });
}
return { json: { outcome, target, update_sequence: target === 'sequence', update_lead: target === 'lead', updates, events } };

// Turns the outcome(s) of this loop round into EVENTS_LOG rows (SPEC 5.6).
const S = $('Lane 5 · Settings to object').first().json;
const TZ = 'Asia/Kolkata';
// ---- event builder (SPEC 5.6)
const now = $now.setZone(TZ);
const used = new Set();
function eventId() {
  let id;
  do { id = `EV-${now.toFormat('yyyyMMddHHmmssSSS')}-${Math.random().toString(36).slice(2, 6).toUpperCase().padEnd(4, '0')}`; } while (used.has(id));
  used.add(id);
  return id;
}
function event({ event_type, entity_type, entity_id = '', status_from = '', status_to = '', channel = '', detail = '', meta = {} }) {
  return {
    event_id: eventId(), ts: now.toFormat("yyyy-MM-dd'T'HH:mm:ssZZ"), lane: 5,
    event_type, entity_type, entity_id, status_from, status_to, channel,
    detail: String(detail).slice(0, 200), meta_json: JSON.stringify(meta),
    execution_id: String($execution.id), demo_mode: S.IS_DEMO ? 'TRUE' : 'FALSE',
  };
}
const rows = [];
const seen = new Set();
$input.all().forEach((item, index) => {
  const decided = $('Lane 5 · Decide outcome').itemMatching(index).json;
  const key = JSON.stringify(decided.events);
  if (seen.has(key)) return;                                       // two SEQUENCES rows were updated for one post: log it once
  seen.add(key);
  for (const e of decided.events) rows.push({ json: event(e) });
});
return rows;

// Pause between two emails (SEND_DELAY_SECONDS). Only after an attempt to send; nothing else needs a pause.
const S = $('Lane 5 · Settings to object').first().json;
const attempted = $input.all().some((item) => ['email_sent', 'email_failed'].includes(item.json.event_type));
return [{ json: { pause_seconds: attempted ? Math.min(60, Math.max(0, Number(S.SEND_DELAY_SECONDS) || 0)) : 0 } }];

// SETTINGS arrives as one item per row (key | value | type | description).
// Turn it into ONE item, e.g. { DEMO_MODE: 'TRUE', GEMINI_MODEL: 'gemini-2.5-flash', ... },
// so every later node can read settings with $('Lane 6 · Settings to object').first().json.KEY
const settings = {};
for (const item of $input.all()) {
  const key = String(item.json.key ?? '').trim();
  if (!key) continue;
  const value = item.json.value;
  settings[key] = typeof value === 'string' ? value.trim() : (value ?? '');
}

// Stop early with a clear message if the sheet is missing something Lane 6 needs.
const required = ["DEMO_MODE","DEMO_MINUTES_PER_DAY","LAUNCH_DATE","EARLY_ACCESS_DAYS","WAITLIST_FORM_URL","SENDER_NAME","SENDER_EMAIL","ALLOWED_DEMO_INBOXES","MAX_SENDS_PER_RUN","SEND_DELAY_SECONDS","MIN_EMAIL_GAP_DAYS","UNSUBSCRIBE_LINE","BRAND_VOICE","GEMINI_MODEL","GROQ_MODEL","AI_TEMPERATURE","AI_WAIT_SECONDS"];
const missing = required.filter((key) => settings[key] === undefined || settings[key] === '');
if (missing.length) {
  throw new Error(`The SETTINGS tab is missing a value for: ${missing.join(', ')}`);
}

// Derived values (SPEC section 5.3). Sheet booleans may come back as true or "TRUE".
settings.IS_DEMO = String(settings.DEMO_MODE).trim().toUpperCase() === 'TRUE';
const demoMinutes = Number(settings.DEMO_MINUTES_PER_DAY);
if (settings.IS_DEMO && !(demoMinutes > 0)) {
  throw new Error('DEMO_MINUTES_PER_DAY must be a number above 0 when DEMO_MODE is TRUE');
}
settings.DAY_MS = settings.IS_DEMO ? demoMinutes * 60 * 1000 : 24 * 60 * 60 * 1000;

return [{ json: settings }];

// Prepares everything the AI prompt and the email templates need from the BRIEF tab.
const S = $('Lane 6 · Settings to object').first().json;
const TZ = 'Asia/Kolkata';
const STAMP = "yyyy-MM-dd'T'HH:mm:ssZZ";
function parseTs(value) {
  if (value === undefined || value === null || String(value).trim() === '') return null;
  const text = String(value).trim();
  const tries = [
    () => DateTime.fromISO(text, { zone: TZ }),
    () => DateTime.fromFormat(text, 'yyyy-MM-dd HH:mm:ss', { zone: TZ }),
    () => DateTime.fromFormat(text, 'yyyy-MM-dd HH:mm', { zone: TZ }),
    () => DateTime.fromFormat(text, 'dd/MM/yyyy HH:mm:ss', { zone: TZ }),
    () => DateTime.fromFormat(text, 'dd/MM/yyyy', { zone: TZ }),
  ];
  for (const attempt of tries) { const d = attempt(); if (d.isValid) return d.setZone(TZ); }
  return null;
}
const parseDate = (value) => parseTs(value)?.startOf('day') ?? null;
const text = (value) => String(value ?? '').trim();
const rows = $input.all().map((item) => item.json).filter((row) => text(row.key));

// Dates shown to people are the REAL dates, even in demo mode (SPEC 5.3).
const launch = parseDate(S.LAUNCH_DATE);
const publicLaunch = launch ? launch.plus({ days: Number(S.EARLY_ACCESS_DAYS) || 0 }) : null;
const fmt = (date) => (date ? date.setLocale('en').toFormat('cccc, d LLLL') : '');
const tokens = { launch_date: fmt(launch), public_launch_date: fmt(publicLaunch), waitlist_form_url: S.WAITLIST_FORM_URL };
const fill = (value) => String(value ?? '').replace(/\{\{\s*(launch_date|public_launch_date|waitlist_form_url)\s*\}\}/g, (token, key) => tokens[key]);

const brief = {};
for (const row of rows) brief[text(row.key)] = fill(text(row.value));
const aiUse = (row) => text(row.ai_use).toLowerCase();

// Facts for outreach prompts: ai_use all + b2b. Rules: ai_use rule. (SPEC 2.2)
const facts = rows.filter((row) => ['all', 'b2b'].includes(aiUse(row)));
const rules = rows.filter((row) => aiUse(row) === 'rule');
const factsText = facts.map((row, index) => `F${String(index + 1).padStart(2, '0')} [${text(row.key)}] ${brief[text(row.key)]}`).join('\n');
const rulesText = rules.map((row, index) => `R${index + 1}. ${brief[text(row.key)]}`).join('\n');

// Numbers the AI opener may mention = numbers that appear in the facts (SPEC 6.4).
const norm = (token) => token.replace(/[₹\s,]/g, '');
const allowedNumbers = new Set();
const allowedRupees = new Set();
for (const match of factsText.matchAll(/₹\s?[\d,]+(?:\.\d+)?/g)) allowedRupees.add(norm(match[0]));
for (const match of factsText.matchAll(/\d[\d,]*(?:\.\d+)?/g)) allowedNumbers.add(norm(match[0]));

return [{ json: {
  brand_name: brief.brand_name, brand_instagram: brief.brand_instagram, collection_name: brief.collection_name,
  founder_name: brief.founder_name, offer_percent: brief.offer_percent,
  launch_date: tokens.launch_date, public_launch_date: tokens.public_launch_date,
  facts_text: factsText, rules_text: rulesText,
  allowed_numbers: [...allowedNumbers], allowed_rupees: [...allowedRupees],
  forbidden_phrases: text(brief.forbidden_phrases).toLowerCase().split(';').map((phrase) => phrase.trim()).filter(Boolean),
} }];

// Decides who gets an email in this run. Output: one item per prospect with an `outcome`:
//   send     = email this prospect now (at most MAX_SENDS_PER_RUN, highest fit_score first)
//   skip     = the row has a problem (missing/invalid field): log it, push it back, never crash the run
//   complete = the sequence has no further active step: mark it sequence_done
// An empty result ends the run quietly (nothing due = no log row).
const S = $('Lane 6 · Settings to object').first().json;
const B = $input.first().json;
const TZ = 'Asia/Kolkata';
const STAMP = "yyyy-MM-dd'T'HH:mm:ssZZ";
function parseTs(value) {
  if (value === undefined || value === null || String(value).trim() === '') return null;
  const text = String(value).trim();
  const tries = [
    () => DateTime.fromISO(text, { zone: TZ }),
    () => DateTime.fromFormat(text, 'yyyy-MM-dd HH:mm:ss', { zone: TZ }),
    () => DateTime.fromFormat(text, 'yyyy-MM-dd HH:mm', { zone: TZ }),
    () => DateTime.fromFormat(text, 'dd/MM/yyyy HH:mm:ss', { zone: TZ }),
    () => DateTime.fromFormat(text, 'dd/MM/yyyy', { zone: TZ }),
  ];
  for (const attempt of tries) { const d = attempt(); if (d.isValid) return d.setZone(TZ); }
  return null;
}
const parseDate = (value) => parseTs(value)?.startOf('day') ?? null;
const now = $now.setZone(TZ);
const text = (value) => String(value ?? '').trim();
const isTrue = (value) => String(value ?? '').trim().toUpperCase() === 'TRUE';
const addDays = (dateTime, days) => dateTime.plus({ milliseconds: Number(days) * S.DAY_MS });
const SEQUENCE_IDS = ['OUTREACH_BOUTIQUE', 'OUTREACH_INFLUENCER'];

// 1) Active email steps per sequence, in step order.
const steps = Object.fromEntries(SEQUENCE_IDS.map((id) => [id, []]));
for (const { json: row } of $('Lane 6 · Read SEQUENCES').all()) {
  const sequenceId = text(row.sequence_id);
  const step = Number(row.step);
  if (!SEQUENCE_IDS.includes(sequenceId) || text(row.channel).toLowerCase() !== 'email' || !isTrue(row.active)) continue;
  if (!Number.isInteger(step) || step < 1) continue;
  steps[sequenceId].push({
    step, step_key: text(row.step_key) || `${sequenceId}#${step}`,
    delay_days: Number.isFinite(Number(row.delay_days)) && text(row.delay_days) !== '' ? Number(row.delay_days) : 1,
    subject_template: String(row.subject_template ?? ''), body_template: String(row.body_template ?? ''),
    ai_personalize: isTrue(row.ai_personalize),
  });
}
for (const list of Object.values(steps)) list.sort((a, b) => a.step - b.step);

// 2) Walk the prospects.
const skips = [];
const completes = [];
const candidates = [];
const gapMs = Number(S.MIN_EMAIL_GAP_DAYS) * S.DAY_MS;
for (const { json: row } of $('Lane 6 · Read PROSPECTS').all()) {
  const id = text(row.prospect_id);
  if (!id) continue;                                            // empty line in the sheet
  const status = text(row.status).toLowerCase();
  if (!['new', 'contacted'].includes(status)) continue;         // paused, replied, interested, ... are never contacted

  const problems = [];
  const nextRaw = text(row.next_action_at);
  const next = parseTs(nextRaw);
  if (nextRaw && !next) problems.push('next_action_at is not a valid timestamp');
  if (next && next.toMillis() > now.toMillis()) continue;       // not due yet
  const lastRaw = text(row.last_contacted_at);
  const last = parseTs(lastRaw);
  if (lastRaw && !last) problems.push('last_contacted_at is not a valid timestamp');

  const email = text(row.email).toLowerCase();
  if (!email) problems.push('missing email');
  else if (!/^[^\s@,;]+@[^\s@,;]+\.[^\s@,;]+$/.test(email)) problems.push('email is not a single valid address');
  if (!text(row.contact_name)) problems.push('missing contact_name');
  if (!text(row.business_name)) problems.push('missing business_name');
  const sequenceId = text(row.sequence_id);
  if (!SEQUENCE_IDS.includes(sequenceId)) problems.push(sequenceId ? `unknown sequence_id ${sequenceId}` : 'missing sequence_id');
  const seqRaw = text(row.seq_step);
  const seqStep = seqRaw === '' ? 0 : Number(seqRaw);
  if (!Number.isInteger(seqStep) || seqStep < 0) problems.push('seq_step is not a whole number');
  const sequenceSteps = steps[sequenceId] || [];
  if (SEQUENCE_IDS.includes(sequenceId) && !sequenceSteps.length) problems.push(`no active email steps for ${sequenceId} in SEQUENCES`);

  if (problems.length) {
    skips.push({ outcome: 'skip', prospect_id: id, status_from: status, reason: problems.join('; '), defer_days: 1, error_node: 'Lane 6 · Pick due prospects', ai: { used: false } });
    continue;
  }
  if (last && now.toMillis() - last.toMillis() < gapMs) continue;   // gapOk (SPEC 5.3): contacted too recently

  const upcoming = sequenceSteps.filter((step) => step.step > seqStep);
  if (!upcoming.length) {
    completes.push({ outcome: 'complete', prospect_id: id, status_from: status, sequence_id: sequenceId, seq_step: seqStep, ai: { used: false } });
    continue;
  }
  const target = upcoming[0];
  const following = upcoming[1];
  candidates.push({
    outcome: 'send', prospect_id: id, to_email: email, status_from: status,
    business_name: text(row.business_name), contact_name: text(row.contact_name), city: text(row.city),
    instagram_handle: text(row.instagram_handle), niche: text(row.niche), notes: text(row.notes), type: text(row.type),
    fit_score: Number(row.fit_score) || 0, sequence_id: sequenceId, seq_step: seqStep, thread_ids: text(row.thread_ids),
    step: target.step, step_key: target.step_key, is_last: !following, next_delay_days: following ? following.delay_days : null,
    subject_template: target.subject_template, body_template: target.body_template, use_ai: target.ai_personalize,
    request_id: `${id}:opener`, ai: { used: false },
  });
}

// 3) Highest fit_score first, at most MAX_SENDS_PER_RUN.
const max = Math.max(0, Math.floor(Number(S.MAX_SENDS_PER_RUN)) || 0);
candidates.sort((a, b) => b.fit_score - a.fit_score || a.prospect_id.localeCompare(b.prospect_id));
const sends = candidates.slice(0, max);
return [...skips, ...completes, ...sends].map((json) => ({ json }));

// Builds the prompt for the current prospect, plus the exact request bodies for Gemini (main)
// and Groq (fallback). Both providers get the same instructions and the same BRIEF facts.
const S = $('Lane 6 · Settings to object').first().json;
const B = $('Lane 6 · Build brief facts').first().json;
