} else if (j.error) {
  spec = { event_type: 'error', ...entity, channel: 'email', detail: `Simulated reply failed: ${errorText(j.error)}`.slice(0, 200), meta: { node: 'Lane 7 · Reply in Demo Customers inbox', message: errorText(j.error).slice(0, 200) } };
} else {
  spec = { event_type: 'demo_reply_simulated', ...entity, channel: 'email', detail: `Simulated "${form.reply_type}" reply to the email sent to ${form.address}`, meta: { reply_type: form.reply_type, address: form.address, thread_id: j.threadId || '' } };
}
return [{ json: event(spec) }];

// SETTINGS arrives as one item per row (key | value | type | description).
// Turn it into ONE item, e.g. { DEMO_MODE: 'TRUE', MAX_SENDS_PER_RUN: '3', ... },
// so every later node can read settings with $('Lane 8 · Settings to object').first().json.KEY
const settings = {};
for (const item of $input.all()) {
  const key = String(item.json.key ?? '').trim();
  if (!key) continue;
  const value = item.json.value;
  settings[key] = typeof value === 'string' ? value.trim() : (value ?? '');
}

// Stop early with a clear message if the sheet is missing something this lane needs.
const required = ["DEMO_MODE","DEMO_MINUTES_PER_DAY","REPORT_TIME","DEMO_REPORT_EVERY_MINUTES","TELEGRAM_OWNER_CHAT_ID","SHEET_URL","BRAND_VOICE","GEMINI_MODEL","GROQ_MODEL","AI_TEMPERATURE"];
const missing = required.filter((key) => settings[key] === undefined || settings[key] === '');
if (missing.length) {
  throw new Error(`The SETTINGS tab is missing a value for: ${missing.join(', ')}`);
}

// Derived values (SPEC section 5.3). Sheet booleans may come back as true or "TRUE".
settings.IS_DEMO = String(settings.DEMO_MODE).trim().toUpperCase() === 'TRUE';
const demoMinutes = Number(settings.DEMO_MINUTES_PER_DAY);
if (settings.IS_DEMO && !(demoMinutes > 0)) {
  throw new Error('DEMO_MINUTES_PER_DAY must be a number above 0 when DEMO_MODE is TRUE');
}
settings.DAY_MS = settings.IS_DEMO ? demoMinutes * 60 * 1000 : 24 * 60 * 60 * 1000;

return [{ json: settings }];

// Decides whether a report is due (SPEC 7.8). L = time of the latest `report_sent` event.
//  demo mode: due if there is no report yet, or now - L >= DEMO_REPORT_EVERY_MINUTES
//  real mode: due if now >= today at REPORT_TIME and L is before today's REPORT_TIME (or there is none)
const S = $('Lane 8 · Settings to object').first().json;
// ---- time helpers (SPEC 5.2 / 5.3)
const TZ = 'Asia/Kolkata';
const STAMP = "yyyy-MM-dd'T'HH:mm:ssZZ";
const nowTs = () => $now.setZone(TZ).toFormat(STAMP);
function parseTs(value) {
  if (value === undefined || value === null || String(value).trim() === '') return null;
  const text = String(value).trim();
  const tries = [
    () => DateTime.fromISO(text, { zone: TZ }),
    () => DateTime.fromFormat(text, 'yyyy-MM-dd HH:mm:ss', { zone: TZ }),
    () => DateTime.fromFormat(text, 'yyyy-MM-dd HH:mm', { zone: TZ }),
    () => DateTime.fromFormat(text, 'dd/MM/yyyy HH:mm:ss', { zone: TZ }),
    () => DateTime.fromFormat(text, 'dd/MM/yyyy', { zone: TZ }),
  ];
  for (const attempt of tries) { const d = attempt(); if (d.isValid) return d.setZone(TZ); }
  return null;
}
const parseDate = (value) => parseTs(value)?.startOf('day') ?? null;
const addDays = (dateTime, days) => dateTime.plus({ milliseconds: Number(days) * S.DAY_MS });
function launchAt(S) {
  if (S.IS_DEMO) return parseTs(S.DEMO_LAUNCH_AT);
  const [hour, minute] = String(S.LAUNCH_TIME).split(':').map(Number);
  return parseDate(S.LAUNCH_DATE)?.set({ hour, minute }) ?? null;
}
const gapOk = (row, now) => !parseTs(row.last_contacted_at) || now.toMillis() - parseTs(row.last_contacted_at).toMillis() >= Number(S.MIN_EMAIL_GAP_DAYS) * S.DAY_MS;
const isTrue = (value) => String(value ?? '').trim().toUpperCase() === 'TRUE';
// Rows read from a sheet; an empty tab comes back as one empty item (and blank rows only have a row_number), so drop those.
const rowsOf = (nodeName) => $(nodeName).all().map((item) => item.json).filter((row) => row && Object.entries(row).some(([key, v]) => key !== 'row_number' && String(v ?? '').trim() !== ''));
const now = $now.setZone(TZ);

let last = null;
for (const row of rowsOf('Lane 8 · Read EVENTS_LOG')) {
  if (String(row.event_type ?? '').trim() !== 'report_sent') continue;
  const t = parseTs(row.ts);
  if (t && (!last || t.toMillis() > last.toMillis())) last = t;
}

let due = false;
let reason = '';
if (S.IS_DEMO) {
  const every = Number(S.DEMO_REPORT_EVERY_MINUTES);
  if (!(every > 0)) throw new Error('DEMO_REPORT_EVERY_MINUTES must be a number above 0 in demo mode');
  if (!last) { due = true; reason = 'no report has been sent yet'; }
  else {
    const minutes = (now.toMillis() - last.toMillis()) / 60000;
    due = minutes >= every;
    reason = `${minutes.toFixed(1)} min since the last report (every ${every})`;
  }
} else {
  const match = /^(\d{1,2}):(\d{2})$/.exec(String(S.REPORT_TIME));
  if (!match) throw new Error('REPORT_TIME must look like 21:00');
  const todayAt = now.startOf('day').set({ hour: Number(match[1]), minute: Number(match[2]) });
  due = now.toMillis() >= todayAt.toMillis() && (!last || last.toMillis() < todayAt.toMillis());
  reason = `today's report time is ${S.REPORT_TIME}`;
}
return [{ json: { due, reason, period_start: last ? last.toFormat(STAMP) : '' } }];

// Computes every metric of SPEC 2.8. "Period" = events after the previous report_sent (all time if there was none).
const S = $('Lane 8 · Settings to object').first().json;
// ---- time helpers (SPEC 5.2 / 5.3)
const TZ = 'Asia/Kolkata';
const STAMP = "yyyy-MM-dd'T'HH:mm:ssZZ";
const nowTs = () => $now.setZone(TZ).toFormat(STAMP);
function parseTs(value) {
  if (value === undefined || value === null || String(value).trim() === '') return null;
  const text = String(value).trim();
  const tries = [
    () => DateTime.fromISO(text, { zone: TZ }),
    () => DateTime.fromFormat(text, 'yyyy-MM-dd HH:mm:ss', { zone: TZ }),
    () => DateTime.fromFormat(text, 'yyyy-MM-dd HH:mm', { zone: TZ }),
    () => DateTime.fromFormat(text, 'dd/MM/yyyy HH:mm:ss', { zone: TZ }),
    () => DateTime.fromFormat(text, 'dd/MM/yyyy', { zone: TZ }),
  ];
  for (const attempt of tries) { const d = attempt(); if (d.isValid) return d.setZone(TZ); }
  return null;
}
const parseDate = (value) => parseTs(value)?.startOf('day') ?? null;
const addDays = (dateTime, days) => dateTime.plus({ milliseconds: Number(days) * S.DAY_MS });
function launchAt(S) {
  if (S.IS_DEMO) return parseTs(S.DEMO_LAUNCH_AT);
  const [hour, minute] = String(S.LAUNCH_TIME).split(':').map(Number);
  return parseDate(S.LAUNCH_DATE)?.set({ hour, minute }) ?? null;
}
const gapOk = (row, now) => !parseTs(row.last_contacted_at) || now.toMillis() - parseTs(row.last_contacted_at).toMillis() >= Number(S.MIN_EMAIL_GAP_DAYS) * S.DAY_MS;
const isTrue = (value) => String(value ?? '').trim().toUpperCase() === 'TRUE';
// Rows read from a sheet; an empty tab comes back as one empty item (and blank rows only have a row_number), so drop those.
const rowsOf = (nodeName) => $(nodeName).all().map((item) => item.json).filter((row) => row && Object.entries(row).some(([key, v]) => key !== 'row_number' && String(v ?? '').trim() !== ''));
const now = $now.setZone(TZ);
const periodStartText = $('Lane 8 · Check if report is due').first().json.period_start;
const periodStart = parseTs(periodStartText);

const content = rowsOf('Lane 8 · Read CONTENT').filter((r) => String(r.content_id ?? '').trim());
const leads = rowsOf('Lane 8 · Read LEADS').filter((r) => String(r.lead_id ?? '').trim());
const prospects = rowsOf('Lane 8 · Read PROSPECTS').filter((r) => String(r.prospect_id ?? '').trim());
const events = rowsOf('Lane 8 · Read EVENTS_LOG').filter((r) => String(r.event_type ?? '').trim());

const txt = (v) => String(v ?? '').trim();
const inPeriod = (e) => !periodStart || (parseTs(e.ts) && parseTs(e.ts).toMillis() > periodStart.toMillis());
const ofType = (type) => events.filter((e) => txt(e.event_type) === type);
const mean = (rows, field) => {
  const values = rows.map((r) => (txt(r[field]) === '' ? NaN : Number(r[field]))).filter(Number.isFinite);
  return values.length ? Math.round(values.reduce((a, b) => a + b, 0) / values.length) : 0;
};
const meta = (e) => { try { return JSON.parse(e.meta_json || '{}'); } catch { return {}; } };

const status = (r) => txt(r.status);
const REPLIED = ['replied', 'interested', 'not_interested', 'do_not_contact', 'won', 'lost'];
const contacted = prospects.filter((p) => Number(txt(p.seq_step) || 0) >= 1).length;
const replied = prospects.filter((p) => REPLIED.includes(status(p))).length;
const emailSent = ofType('email_sent');

const metrics = {
  content_total: content.length,
  content_pending_approval: content.filter((r) => status(r) === 'pending_approval').length,
  content_approved: content.filter((r) => ['approved', 'publishing'].includes(status(r))).length,
  content_published: content.filter((r) => status(r) === 'published').length,
  content_avg_seo_score: mean(content, 'seo_score'),
  leads_total: leads.length,
  leads_new_period: ofType('lead_captured').filter(inPeriod).length,
  leads_hot: leads.filter((r) => txt(r.segment) === 'hot' || status(r) === 'hot').length,
  leads_warm: leads.filter((r) => txt(r.segment) === 'warm').length,
  leads_cold: leads.filter((r) => txt(r.segment) === 'cold').length,
  leads_avg_score: mean(leads, 'score'),
  leads_unsubscribed: leads.filter((r) => status(r) === 'unsubscribed').length,
  leads_blocked: leads.filter((r) => status(r) === 'blocked').length,
  emails_sent_total: emailSent.length,
  emails_sent_period: emailSent.filter(inPeriod).length,
  emails_blocked_total: ofType('email_blocked').length,
  launch_emails_sent: emailSent.filter((e) => txt(e.lane) === '5').length,
  prospects_total: prospects.length,
  prospects_contacted: contacted,
  prospects_replied: replied,
  prospects_interested: prospects.filter((p) => ['interested', 'won'].includes(status(p))).length,
  outreach_reply_rate_pct: contacted > 0 ? Math.round((replied / contacted) * 1000) / 10 : 0,
  replies_total: ofType('reply_received').length,
  hot_alerts_total: ofType('hot_alert_sent').length,
  channel_posts_total: ofType('content_published').filter((e) => txt(e.channel) === 'telegram_channel').length + ofType('launch_post_published').length,
  ai_calls_total: ofType('ai_call').length,
  ai_fallbacks_total: ofType('ai_fallback').length,
  ai_failures_total: ofType('ai_failed').length,
  errors_period: ofType('error').filter(inPeriod).length,
  last_report_at: now.toFormat(STAMP),
};
return [{ json: { metrics, period_start: periodStartText, period_text: periodStart ? `since ${periodStart.toFormat('d LLL HH:mm')}` : 'all time (first report)' } }];

// One clean row per metric: ONLY metric_key, value and updated_at (SPEC 5.4: DASHBOARD is written by Append or Update on metric_key).
const { metrics } = $input.first().json;
const ts = $now.setZone('Asia/Kolkata').toFormat("yyyy-MM-dd'T'HH:mm:ssZZ");
return Object.entries(metrics).map(([metric_key, value]) => ({ json: { metric_key, value, updated_at: ts } }));

// Builds the prompt for the optional "3 insights" AI call plus the exact request bodies for Gemini (main) and Groq (fallback).
// Only the computed metrics are sent (as JSON). No other facts are given, and none may be invented.
const S = $('Lane 8 · Settings to object').first().json;
const computed = $('Lane 8 · Compute metrics').first().json;
const { last_report_at, ...metricsForAi } = computed.metrics;       // a timestamp only invites made-up numbers

const system = [
  'You write the short management summary of a campaign report for Kaya Jewels, a handmade jewellery brand from Jaipur.',
  '',
  'BRAND VOICE',
  S.BRAND_VOICE,
  '',
  'RULES (most important)',
  '1. The METRICS JSON in the user message is the only source of truth. Use nothing else.',
  '2. Mention only numbers that appear in the METRICS JSON, written exactly as they appear there. Never add, subtract, round, convert or estimate numbers, and never write any other number (no dates, no percentages that are not in the JSON, no counts of items).',
  '3. Never invent causes, events, customers, people, products, prices, dates or quotes.',
  '4. Write exactly 3 insights, each at most 30 words, plain text without markdown: (1) what happened, (2) what is working, (3) one recommended action.',
  '5. Answer with one JSON object only: { "insights": [string, string, string] }',
].join('\n');
const prompt = `METRICS (JSON, ${computed.period_text}):\n${JSON.stringify(metricsForAi)}`;

const temperature = Number(S.AI_TEMPERATURE);
const geminiBody = {
  systemInstruction: { parts: [{ text: system }] },
  contents: [{ role: 'user', parts: [{ text: prompt }] }],
  generationConfig: {
    temperature: Number.isFinite(temperature) ? temperature : 0.7, maxOutputTokens: 8192, responseMimeType: 'application/json',
    responseSchema: { type: 'OBJECT', properties: { insights: { type: 'ARRAY', items: { type: 'STRING' }, minItems: 3, maxItems: 3 } }, required: ['insights'], propertyOrdering: ['insights'] },
  },
};
const budget = String(S.GEMINI_THINKING_BUDGET ?? '').trim();
if (budget !== '' && Number.isFinite(Number(budget))) geminiBody.generationConfig.thinkingConfig = { thinkingBudget: Number(budget) };

const groqBody = {
  model: S.GROQ_MODEL, temperature: Number.isFinite(temperature) ? temperature : 0.7, max_tokens: 1500,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: `${system}\nReturn ONLY one JSON object with exactly this shape: ${JSON.stringify({ insights: ['what happened', 'what is working', 'one recommended action'] })}` },
    { role: 'user', content: prompt },
  ],
};
return [{ json: { gemini_model: S.GEMINI_MODEL, groq_model: S.GROQ_MODEL, started_at: Date.now(), request_id: `report:${$now.setZone('Asia/Kolkata').toFormat('yyyyMMdd-HHmmss')}:insights`, gemini_body: geminiBody, groq_body: groqBody, allowed_numbers: Object.values(metricsForAi).map((v) => String(Number(v))) } }];

// Pull the answer text out of Gemini's response. If the HTTP call failed (after its retries) the item only has an "error"
// field; we pass that on so the check can switch to Groq.
const request = $('Lane 8 · Build AI request').first().json;
const response = $input.first().json;

let text = '';
let error = '';
if (response.error) {
  const { message, description } = response.error;
  const detail = [message, description].filter(Boolean).join(' - ') || JSON.stringify(response.error);
  error = `Gemini call failed: ${String(detail).slice(0, 300)}`;
} else {
  const candidate = (response.candidates || [])[0];
  const parts = candidate?.content?.parts || [];
  text = parts.filter((part) => !part.thought && typeof part.text === 'string').map((part) => part.text).join('');
  const finish = candidate?.finishReason || response.promptFeedback?.blockReason || 'unknown';
  if (!text) error = `Gemini returned no text (reason: ${finish})`;
  else if (finish !== 'STOP') error = `Gemini stopped early (reason: ${finish})`;
}
return [{ json: { provider: 'gemini', model: request.gemini_model, text, error, fallback_reason: '' } }];

// Same check for both providers: valid JSON with 3 insights, and NO number that is not in the metrics.
// A bad answer from Gemini sends the job to the Groq fallback (try_groq = true). A bad answer from Groq = AI failure (no insights).
const request = $('Lane 8 · Build AI request').first().json;
const reply = $input.first().json;

function parseJson(text) {
  let clean = String(text || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  const start = clean.indexOf('{');
  const end = clean.lastIndexOf('}');
  if (start !== -1 && end > start) clean = clean.slice(start, end + 1);
  return JSON.parse(clean);
}

let insights = null;
let error = reply.error || '';
if (!error) {
  try {
    const data = parseJson(reply.text);
    const list = Array.isArray(data.insights) ? data.insights.map((s) => String(s ?? '').trim()).filter(Boolean) : [];
    if (list.length < 3) error = `${reply.provider} answer is incomplete: needs 3 insights`;
    else insights = list.slice(0, 3);
  } catch (parseError) {
    error = `${reply.provider} answer is not valid JSON: ${parseError.message}`;
  }
}
if (!error) {
  // Reject any insight with a number that is not one of the metrics we supplied.
  const allowed = new Set(request.allowed_numbers);
  const invented = [];
  for (const sentence of insights) {
    for (const found of sentence.match(/\d[\d,]*(?:\.\d+)?/g) || []) {
      const value = String(Number(found.replace(/,/g, '')));
      if (!allowed.has(value)) invented.push(found);
    }
  }
  if (invented.length) { error = `${reply.provider} used number(s) that are not in the metrics: ${[...new Set(invented)].join(', ')}`; insights = null; }
}

const ok = !error;
const tryGroq = !ok && reply.provider === 'gemini';
return [{
  json: {
    request_id: request.request_id, ai_ok: ok, ai_provider: reply.provider, ai_model: reply.model, ai_error: error,
    fallback_reason: reply.fallback_reason || '', try_groq: tryGroq, duration_ms: Date.now() - request.started_at,
    insights: ok ? insights : [], groq_body: tryGroq ? request.groq_body : null,
  },
}];

// Pull the answer text out of Groq's (OpenAI-style) response, and remember why we fell back.
const request = $('Lane 8 · Build AI request').first().json;
const response = $input.first().json;
const fallbackReason = $('Lane 8 · Need Groq fallback?').first(0)?.json?.ai_error || '';

let text = '';
let error = '';
if (response.error) {
  const { message, description } = response.error;
  const detail = [message, description].filter(Boolean).join(' - ') || JSON.stringify(response.error);
  error = `Groq call failed: ${String(detail).slice(0, 300)}`;
} else {
  const choice = (response.choices || [])[0];
  text = choice?.message?.content || '';
  if (!text) error = `Groq returned no text (reason: ${choice?.finish_reason || 'unknown'})`;
}
return [{ json: { provider: 'groq', model: request.groq_model, text, error, fallback_reason: fallbackReason } }];

// Builds the Telegram report for the owner (SPEC 7.8). All numbers come from the computed metrics; insights (if any) from the AI check.
const S = $('Lane 8 · Settings to object').first().json;
const computed = $('Lane 8 · Compute metrics').first().json;
const m = computed.metrics;
const ai = $input.first().json;
const tg = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const lines = [
  '📊 <b>Kaya Jewels · campaign report</b>',
  `<i>Period: ${tg(computed.period_text)}</i>`,
  '',
  `<b>Content</b>: ${m.content_pending_approval} waiting for approval · ${m.content_published} published (of ${m.content_total})`,
  `<b>Leads</b>: ${m.leads_total} total · ${m.leads_new_period} new this period · ${m.leads_hot} hot`,
  `<b>Emails</b>: ${m.emails_sent_total} sent in total (${m.emails_sent_period} this period)`,
  `<b>Outreach</b>: ${m.prospects_contacted} contacted · ${m.prospects_replied} replied · ${m.prospects_interested} interested · reply rate ${m.outreach_reply_rate_pct}%`,
  `<b>AI</b>: ${m.ai_fallbacks_total} fallbacks to Groq`,
  `<b>Errors</b>: ${m.errors_period} this period`,
];
if (ai.ai_ok && ai.insights?.length) {
  lines.push('', '<b>Insights</b>');
  for (const insight of ai.insights) lines.push(`• ${tg(insight)}`);
}
lines.push('', `<a href="${String(S.SHEET_URL).replace(/&/g, '&amp;').replace(/"/g, '&quot;')}">Open the campaign sheet</a>`);
return [{ json: { chat_id: String(S.TELEGRAM_OWNER_CHAT_ID), text: lines.join('\n').slice(0, 4000), ai } }];

// Writes what happened to EVENTS_LOG (SPEC 5.6): the dashboard write, the AI call (+ fallback / failure) and the report itself.
const S = $('Lane 8 · Settings to object').first().json;
const TZ = 'Asia/Kolkata';
// ---- event builder (SPEC 5.6)
const now = $now.setZone(TZ);
const used = new Set();
function eventId() {
  let id;
  do { id = `EV-${now.toFormat('yyyyMMddHHmmssSSS')}-${Math.random().toString(36).slice(2, 6).toUpperCase().padEnd(4, '0')}`; } while (used.has(id));
  used.add(id);
  return id;
}
function event({ event_type, entity_type, entity_id = '', status_from = '', status_to = '', channel = '', detail = '', meta = {} }) {
  return {
    event_id: eventId(), ts: now.toFormat("yyyy-MM-dd'T'HH:mm:ssZZ"), lane: 8,
    event_type, entity_type, entity_id, status_from, status_to, channel,
    detail: String(detail).slice(0, 200), meta_json: JSON.stringify(meta),
    execution_id: String($execution.id), demo_mode: S.IS_DEMO ? 'TRUE' : 'FALSE',
  };
}
const computed = $('Lane 8 · Compute metrics').first().json;
const rowsWritten = $('Lane 8 · Back to one item').first().json.dashboard_rows;
const ai = $('Lane 8 · Build report message').first().json.ai;   // the final AI result (Gemini, or Groq after a fallback)
const telegram = $input.first().json;
const reportId = `R-${now.toFormat('yyyyMMdd-HHmmss')}`;
const events = [];

events.push(event({ event_type: 'dashboard_updated', entity_type: 'report', entity_id: reportId, channel: 'sheet',
  detail: `DASHBOARD updated with ${rowsWritten} metrics`, meta: { metrics: rowsWritten } }));

const aiMeta = { provider: ai.ai_provider, model: ai.ai_model, ok: ai.ai_ok, purpose: 'report_insights', duration_ms: ai.duration_ms };
events.push(event({ event_type: 'ai_call', entity_type: 'ai', entity_id: ai.request_id, channel: 'ai',
  detail: `report insights: ${ai.ai_ok ? 'ok' : 'failed'} via ${ai.ai_provider}`, meta: aiMeta }));
if (ai.ai_provider === 'groq') {
  events.push(event({ event_type: 'ai_fallback', entity_type: 'ai', entity_id: ai.request_id, channel: 'ai',
    detail: `Gemini failed, used Groq: ${ai.fallback_reason}`, meta: { ...aiMeta, reason: ai.fallback_reason } }));
}
if (!ai.ai_ok) {
  events.push(event({ event_type: 'ai_failed', entity_type: 'ai', entity_id: ai.request_id, channel: 'ai',
    detail: `${ai.ai_error} (report sent without insights)`, meta: { ...aiMeta, error: ai.ai_error } }));
}

const sent = telegram.ok === true && telegram.result?.message_id !== undefined && !telegram.error;
if (sent) {
  events.push(event({ event_type: 'report_sent', entity_type: 'report', entity_id: reportId, channel: 'telegram_owner',
    detail: `Report sent to the owner (${computed.period_text})`, meta: { period_start: computed.period_start, message_id: telegram.result.message_id } }));
} else {
  const message = typeof telegram.error === 'string' ? telegram.error : (telegram.error?.message || telegram.description || 'Telegram returned no message id');
  events.push(event({ event_type: 'error', entity_type: 'report', entity_id: reportId, channel: 'telegram_owner',
    detail: `Report not sent to Telegram (the dashboard was still updated): ${message}`, meta: { node: 'Lane 8 · Send report', message: String(message).slice(0, 300) } }));
}
return events.map((json) => ({ json }));
